pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // Constrain inputs: _tos length must equal v length and be > 0 per require
        vm.assume(_tos.length > 0 && _tos.length == v.length);

        // Track successful calls via a mock that only allows one call per address
        // We need a way to count transfers: deploy a simple ERC20-like mock that logs calls
        // Since we cannot import external contracts, we use vm.record and vm.accesses
        // Instead, we can use a counter on the token contract we deploy
        // But the simplest: just check that the function returns true (no revert) and call succeeded

        // Record all external calls made
        vm.record();

        bool result = c.transfer(from, caddress, _tos, v);

        (address[] memory accessedAddresses, bytes4[] memory accessedSelectors) = vm.accesses(address(c));

        // Count the number of transferFrom calls (should equal _tos.length)
        uint transferFromCount = 0;
        for (uint i = 0; i < accessedSelectors.length; i++) {
            if (accessedSelectors[i] == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
                transferFromCount++;
            }
        }

        // The property: number of transferFrom calls equals the length of _tos
        assertTrue(transferFromCount == _tos.length, "Transfer count mismatch");
    }
}
